// JavaScript WebSocket example
const socket = new WebSocket('wss://chat.example.com');

// When connection opens
socket.onopen = () => {
    socket.send('Hello!');
};

// When message arrives (server pushed it)
socket.onmessage = (event) => {
    console.log('Got:', event.data);
};

